(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-943":{scenario:{company:"Công ty CP Tín chỉ Carbon Đồng Xanh",supervisor:{name:"Mai Tuấn Kiệt",role:{vi:"Giám đốc Phát triển dự án carbon",en:"Carbon Project Development Director"}},ref_code:"MR-SOL07",title:{vi:"Đúng hệ số lưới. Đúng lượng giảm phát thải. Tín chỉ toàn vẹn.",en:"Right grid factor. Right reductions. Credits with integrity."},brief:{vi:"Bạn lập báo cáo giám sát MR-SOL07 cho dự án điện mặt trời áp mái nối lưới ở một khu công nghiệp, đăng ký theo tiêu chuẩn tín chỉ tự nguyện (mô phỏng). Năm giám sát, điện năng phát lên lưới đo được 72500 MWh. Hệ số lưới mô phỏng: biên vận hành EF_OM 0.79, biên xây dựng EF_BM 0.62 tCO2/MWh. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa loại hệ số phát thải áp dụng và lượng giảm phát thải (tCO2e, làm tròn xuống số nguyên), rồi lập báo cáo có căn cứ.",en:"You are preparing monitoring report MR-SOL07 for a grid-connected rooftop solar project in an industrial park, registered under a voluntary carbon standard (training). Metered net supply to the grid in the monitoring year was 72500 MWh. Training grid factors: operating margin EF_OM 0.79 and build margin EF_BM 0.62 tCO2/MWh. Compare the draft with the approved file, correct the emission factor type and the emission reductions (tCO2e, rounded down to a whole number), then write an evidence-based report."},reference_title:{vi:"Tài liệu thiết kế dự án & phương pháp luận đã đăng ký · MR-SOL07",en:"Registered project design document & methodology · MR-SOL07"},fields:[{id:"EF_TYPE",label:{vi:"Loại hệ số phát thải lưới áp dụng",en:"Grid emission factor type applied"},initial:"EF-OM",expected:"EF-CM",choices:["EF-OM","EF-BM","EF-CM"],reference:"Phương pháp luận đã đăng ký mục 5",hint:{vi:"Dự án năng lượng tái tạo nối lưới dùng hệ số biên kết hợp, gộp có trọng số biên vận hành và biên xây dựng.",en:"Grid-connected renewable projects use the combined margin, a weighted mix of operating and build margins."}},{id:"ER_TCO2E",label:{vi:"Lượng giảm phát thải năm giám sát (tCO2e)",en:"Emission reductions in the monitoring year (tCO2e)"},initial:"57275",expected:"54193",reference:"Bảng tính giảm phát thải",ref_value:{vi:"Điện phát lên lưới 72500 MWh; EF_OM 0.79; EF_BM 0.62 tCO2/MWh; phát thải dự án và rò rỉ bằng 0",en:"Net grid supply 72500 MWh; EF_OM 0.79; EF_BM 0.62 tCO2/MWh; project emissions and leakage zero"},hint:{vi:"Tính hệ số biên kết hợp với trọng số dành cho điện mặt trời trước, rồi nhân với điện năng và làm tròn xuống.",en:"Compute the combined margin with the solar weights first, then multiply by energy and round down."}}],sop32:{vi:"Điện mặt trời, điện gió: EF_CM = 0.75 x EF_OM + 0.25 x EF_BM; giảm phát thải = điện phát lên lưới x EF_CM - phát thải dự án - rò rỉ; làm tròn xuống tấn nguyên (nguyên tắc thận trọng).",en:"Solar and wind: EF_CM = 0.75 x EF_OM + 0.25 x EF_BM; emission reductions = net grid supply x EF_CM - project emissions - leakage; round down to whole tonnes (conservativeness)."},context:{label:"BÁO CÁO GIÁM SÁT / MR-SOL07",metrics:[{label:{vi:"Điện phát lên lưới",en:"Net grid supply"},value:"72,500 MWh"},{label:{vi:"EF_OM mô phỏng",en:"Training EF_OM"},value:"0.79 tCO2/MWh"},{label:{vi:"EF_BM mô phỏng",en:"Training EF_BM"},value:"0.62 tCO2/MWh"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Gộp luôn sản lượng 4 tháng trước ngày bắt đầu giai đoạn tín dụng vào báo cáo cho đủ 60000 tín chỉ đã ký bán kỳ hạn. Đơn vị thẩm tra không soát từng tháng đâu.”",en:"The Commercial Director texts: “Add the 4 months of output before the crediting period start date so we reach the 60000 credits sold forward. The verifier will not check month by month.”"},options:{safe:{vi:"Từ chối đưa sản lượng ngoài giai đoạn tín dụng; chỉ báo cáo dữ liệu đo trong kỳ, minh bạch với đơn vị thẩm tra; báo Giám đốc Phát triển dự án và đề xuất đàm phán lại khối lượng với người mua.",en:"Refuse to add output outside the crediting period; report only in-period metered data, stay transparent with the verifier, inform the Project Director and propose renegotiating volumes with the buyer."},shortcut:{vi:"Gộp sản lượng 4 tháng trước giai đoạn tín dụng để đủ khối lượng đã ký bán.",en:"Add the 4 pre-crediting months to reach the contracted volume."},wait:{vi:"Không phản hồi, nộp báo cáo nháp và để người mua tự xử lý phần thiếu hụt.",en:"Do not respond, submit the draft and leave the buyer to handle the shortfall."}},questions:{vi:["Vì sao báo cáo phải dùng EF-CM chứ không phải EF-OM? Trích căn cứ trong phương pháp luận đã đăng ký.","Trình bày cách tính lượng giảm phát thải và rủi ro toàn vẹn tín chỉ nếu đưa sản lượng ngoài giai đoạn tín dụng vào báo cáo."],en:["Why must the report use EF-CM rather than EF-OM? Cite the registered methodology.","Explain how you calculated the reductions and the credit integrity risk of including output outside the crediting period."]},hints:{vi:["Đọc mục hệ số phát thải của phương pháp luận đã đăng ký và đánh dấu loại hệ số đang dùng sai.","Tính EF_CM với trọng số cho điện mặt trời theo SOP mục 3.2 rồi mới nhân điện năng và làm tròn xuống.","Đọc lại SOP mục 4.2: chỉ được cấp tín chỉ cho giảm phát thải đo được trong giai đoạn tín dụng đã đăng ký."],en:["Read the emission factor section of the registered methodology and flag the wrong factor type.","Compute EF_CM with the solar weights in SOP 3.2, then multiply by energy and round down.","Re-read SOP 4.2: credits are issued only for reductions measured within the registered crediting period."]}},learning:{summary:{vi:"Chuyên viên phát triển dự án tín chỉ carbon xác định, thiết kế và đưa dự án giảm phát thải hoặc hấp thụ khí nhà kính qua toàn bộ chu trình: đánh giá khả thi, chọn phương pháp luận, chứng minh tính bổ sung, lập tài liệu thiết kế dự án, thẩm định, đăng ký, giám sát, thẩm tra và cấp tín chỉ. Nghề đòi hỏi kiến thức kỹ thuật, tài chính, pháp lý thị trường carbon và cam kết tuyệt đối với tính toàn vẹn môi trường.",en:"A carbon credit project developer identifies and designs emission reduction or removal projects and takes them through the full cycle: feasibility, methodology selection, additionality, project design document, validation, registration, monitoring, verification and issuance. The role needs technical, financial and carbon market legal knowledge and an absolute commitment to environmental integrity."},responsibilities:{vi:["Sàng lọc cơ hội dự án, đánh giá tiềm năng giảm phát thải và tính khả thi tài chính.","Chọn phương pháp luận, chứng minh tính bổ sung và lập tài liệu thiết kế dự án (PDD).","Làm việc với đơn vị thẩm định, thẩm tra (VVB) và cơ quan đăng ký tín chỉ.","Xây dựng kế hoạch giám sát, thu thập dữ liệu và lập báo cáo giám sát định kỳ.","Đàm phán hợp đồng mua bán tín chỉ, quản lý rủi ro giao hàng và chống tính trùng."],en:["Screen project opportunities and assess reduction potential and financial feasibility.","Select methodologies, demonstrate additionality and write the project design document (PDD).","Work with validation and verification bodies (VVBs) and the credit registry.","Build monitoring plans, collect data and prepare periodic monitoring reports.","Negotiate credit purchase agreements, manage delivery risk and prevent double counting."]},competencies:[{name:{vi:"Phương pháp luận & MRV",en:"Methodologies & MRV"},desc:{vi:"Áp dụng đúng công thức đường cơ sở, phát thải dự án, rò rỉ và kế hoạch đo đạc, báo cáo, thẩm tra.",en:"Apply baseline, project emission and leakage formulas and measurement, reporting and verification plans correctly."}},{name:{vi:"Tính bổ sung & đường cơ sở",en:"Additionality & baselines"},desc:{vi:"Phân tích rào cản, đầu tư và thực tiễn phổ biến để chứng minh dự án không phải kịch bản thông thường.",en:"Use barrier, investment and common practice analysis to show the project is not business as usual."}},{name:{vi:"Mô hình tài chính carbon",en:"Carbon finance modeling"},desc:{vi:"Dự báo dòng tín chỉ, chi phí chu trình và độ nhạy theo giá, sản lượng.",en:"Forecast credit flows, cycle costs and sensitivity to price and volume."}},{name:{vi:"Quan hệ thẩm định & đăng ký",en:"Validation & registry relations"},desc:{vi:"Chuẩn bị bằng chứng, trả lời phát hiện của VVB và theo dõi thủ tục cấp tín chỉ.",en:"Prepare evidence, answer VVB findings and track issuance procedures."}},{name:{vi:"Toàn vẹn tín chỉ",en:"Credit integrity"},desc:{vi:"Áp dụng nguyên tắc thận trọng, từ chối thổi phồng hay tính trùng và báo cáo áp lực sai lệch.",en:"Apply conservativeness, refuse inflation or double counting and escalate pressure to misstate."}}],knowledge:{vi:["Thỏa thuận Paris, Điều 6.2 và Điều 6.4, điều chỉnh tương ứng và yêu cầu chống tính trùng.","Công cụ tính hệ số phát thải lưới điện của CDM (Tool 07): biên vận hành, biên xây dựng và biên kết hợp.","ISO 14064-2:2019 về định lượng giảm phát thải cấp dự án và ISO 14064-3:2019 về thẩm định, thẩm tra.","Nguyên tắc Tín chỉ Carbon Cốt lõi (Core Carbon Principles) của ICVCM: bổ sung, lâu dài, định lượng chặt chẽ, không tính trùng.","Nghị định 06/2022/NĐ-CP và lộ trình phát triển thị trường carbon trong nước của Việt Nam."],en:["The Paris Agreement Articles 6.2 and 6.4, corresponding adjustments and double counting safeguards.","The CDM tool to calculate the emission factor for an electricity system (Tool 07): operating, build and combined margins.","ISO 14064-2:2019 on project-level GHG reduction quantification and ISO 14064-3:2019 on validation and verification.","The ICVCM Core Carbon Principles: additionality, permanence, robust quantification and no double counting.","Decree 06/2022/ND-CP and Vietnam's roadmap for a domestic carbon market."]},tools:["Bảng tính hệ số phát thải lưới","Mô hình tài chính dự án carbon","Phần mềm quản lý dữ liệu giám sát (MRV)","Hệ thống đăng ký tín chỉ (registry)","GIS và ảnh viễn thám","Đồng hồ đo đếm điện năng đã hiệu chuẩn"],kpis:{vi:["Tỷ lệ tín chỉ được cấp so với lượng dự kiến trong PDD.","Số yêu cầu khắc phục của đơn vị thẩm tra mỗi kỳ (càng ít càng tốt).","Thời gian từ khi kết thúc kỳ giám sát đến khi cấp tín chỉ.","Số sự cố tính trùng hoặc phải hủy tín chỉ (mục tiêu bằng 0)."],en:["Credits issued against the PDD estimate.","Corrective action requests from the verifier per period (fewer is better).","Time from the end of a monitoring period to issuance.","Double counting incidents or cancelled credits (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra dữ liệu đo đếm điện năng, nhật ký hiệu chuẩn đồng hồ và các khoảng trống dữ liệu.",en:"Check metered energy data, meter calibration logs and data gaps."},{time:"09:30",vi:"Cập nhật bảng tính giảm phát thải theo phương pháp luận đã đăng ký.",en:"Update the reduction calculations under the registered methodology."},{time:"13:30",vi:"Trả lời câu hỏi của đơn vị thẩm tra và bổ sung bằng chứng cho các phát hiện.",en:"Answer verifier queries and add evidence for open findings."},{time:"15:30",vi:"Họp với người mua về tiến độ giao tín chỉ và điều khoản hợp đồng.",en:"Meet the buyer about credit delivery schedules and contract terms."},{time:"17:00",vi:"Rà soát cơ hội dự án mới, đánh giá sơ bộ tính bổ sung và rủi ro.",en:"Screen new project opportunities for additionality and risk."}],mistakes:{vi:["Dùng biên vận hành thay cho biên kết hợp, làm thổi phồng lượng giảm phát thải.","Làm tròn lên hoặc chọn giả định lạc quan, vi phạm nguyên tắc thận trọng.","Bán cùng một lượng tín chỉ cho hai bên hoặc để chủ dự án vẫn tuyên bố trung hòa trên lượng đã bán, gây tính trùng."],en:["Using the operating margin instead of the combined margin, inflating reductions.","Rounding up or choosing optimistic assumptions, breaching conservativeness.","Selling the same credits twice or letting the host still claim neutrality on sold credits, causing double counting."]},career:[{vi:"Chuyên viên phân tích carbon",en:"Carbon analyst"},{vi:"Chuyên viên phát triển dự án carbon",en:"Carbon project developer"},{vi:"Quản lý danh mục dự án carbon",en:"Carbon portfolio manager"},{vi:"Giám đốc phát triển thị trường carbon",en:"Director of Carbon Markets"}],glossary:[{term:"Combined margin",vi:"Biên kết hợp: hệ số phát thải lưới gộp có trọng số giữa biên vận hành và biên xây dựng.",en:"A weighted average of the operating and build margin grid emission factors."},{term:"Additionality",vi:"Tính bổ sung: giảm phát thải chỉ xảy ra nhờ cơ chế tín chỉ, không phải hoạt động thông thường hay bắt buộc.",en:"Reductions happen only because of carbon finance, not business as usual or legal obligation."},{term:"Crediting period",vi:"Giai đoạn tín dụng: khoảng thời gian dự án được cấp tín chỉ cho giảm phát thải đã thẩm tra.",en:"The period during which verified reductions can earn credits."},{term:"VVB",vi:"Đơn vị thẩm định, thẩm tra độc lập được công nhận để đánh giá dự án và báo cáo giám sát.",en:"An accredited validation and verification body that assesses projects and monitoring reports."},{term:"Double counting",vi:"Tính trùng: cùng một lượng giảm phát thải được cấp, bán hoặc tuyên bố nhiều lần.",en:"The same reduction being issued, sold or claimed more than once."}],quiz:[{q:{vi:"Dự án điện gió có EF_OM 0.8 và EF_BM 0.6 tCO2/MWh, trọng số 0.75 và 0.25. Hệ số biên kết hợp EF_CM là bao nhiêu?",en:"A wind project has EF_OM 0.8 and EF_BM 0.6 tCO2/MWh with weights 0.75 and 0.25. What is EF_CM?"},options:{vi:["0.70","0.75","0.65","0.80"],en:["0.70","0.75","0.65","0.80"]},answer:1,explain:{vi:"Biên kết hợp: EF_CM = 0.75 x 0.8 + 0.25 x 0.6 = 0.6 + 0.15 = 0.75 tCO2/MWh.",en:"EF_CM = 0.75 x 0.8 + 0.25 x 0.6 = 0.6 + 0.15 = 0.75 tCO2/MWh."}},{q:{vi:"Nguyên tắc thận trọng yêu cầu gì khi dữ liệu có độ không chắc chắn?",en:"What does conservativeness require when data is uncertain?"},options:{vi:["Chọn giả định làm giảm lượng tín chỉ tính được","Chọn giả định có lợi nhất","Bỏ qua dữ liệu thiếu","Làm tròn lên"],en:["Choose assumptions that lower the credits claimed","Choose the most favorable assumptions","Ignore missing data","Round up"]},answer:0,explain:{vi:"Thận trọng nghĩa là không đánh giá quá cao giảm phát thải; khi nghi ngờ, chọn phương án cho ít tín chỉ hơn.",en:"Conservativeness means never overstating reductions; when in doubt, choose the option yielding fewer credits."}},{q:{vi:"Người mua muốn chủ dự án vẫn tuyên bố trung hòa carbon trên lượng tín chỉ đã bán cho họ. Bạn làm gì?",en:"The buyer is happy for the host to keep claiming carbon neutrality on credits sold to the buyer. What do you do?"},options:{vi:["Đồng ý vì cả hai cùng có lợi","Đồng ý nếu không công bố ra ngoài","Im lặng để hai bên tự thỏa thuận","Từ chối vì đó là tính trùng; ghi rõ quyền tuyên bố trong hợp đồng và báo cấp trên"],en:["Agree since both benefit","Agree if it stays private","Stay silent and let them agree","Refuse as double claiming; define claim rights in the contract and escalate"]},answer:3,explain:{vi:"Một tấn giảm phát thải chỉ được tuyên bố một lần; tuyên bố trùng làm mất tính toàn vẹn của tín chỉ.",en:"One tonne can be claimed only once; double claiming destroys credit integrity."}},{q:{vi:"Tiêu chuẩn nào hướng dẫn định lượng, giám sát và báo cáo giảm phát thải cấp dự án?",en:"Which standard guides project-level quantification, monitoring and reporting of GHG reductions?"},options:{vi:["ISO 14064-1","ISO 9001","ISO 14064-2","ISO 50001"],en:["ISO 14064-1","ISO 9001","ISO 14064-2","ISO 50001"]},answer:2,explain:{vi:"ISO 14064-2 dành cho cấp dự án; ISO 14064-1 dành cho kiểm kê cấp tổ chức.",en:"ISO 14064-2 covers projects; ISO 14064-1 covers organization-level inventories."}}],tools_en:["Grid emission factor spreadsheet","Carbon project financial model","Monitoring data management software (MRV)","Carbon credit registry","GIS and remote sensing imagery","Calibrated electricity meter"]}}})})(window.KKR);
